let myShader;



 function setting() 
 {

 }
 function setup()
 {
 createCanvas(500, 500, WEBGL);
 //noStroke();
 //fill(255,0,0);
 myShader = loadShader("https://openprocessing.org/sketch/1078005/files/frag.glsl","vert.glsl");


 myShader.set("uFrameCount", 1);

 GLContext.getCurrentGL().getGL3().glEnable(GL3.GL_PROGRAM_POINT_SIZE);

 }

 function draw()
 {

 shader(myShader); 

 background(0);



 // let the frameCount to the shader
 myShader.set("uFrameCount", frameCount*2);


 translate(200,200,0);
 // let our geometry on the let and let axes
 rotateX(frameCount * 0.02);
 rotateY(frameCount * 0.01);

 // let some geometry to the screen
 // We're going to tessellate the sphere a bit so we have some more geometry to work with

 sphereDetail(width / 4);
 sphere(200);


 }

